package main

import (
	"sync"
)

// ThreadSafeCounter обеспечивает потокобезопасный инкремент
type ThreadSafeCounter struct {
	mu    sync.Mutex
	value int
}

func (c *ThreadSafeCounter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.value++
}

func (c *ThreadSafeCounter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.value
}

