package main

import (
	"sync"
	"testing"
)

func TestThreadSafeCounter(t *testing.T) {
	c := &ThreadSafeCounter{}
	var wg sync.WaitGroup

	iterations := 100
	wg.Add(iterations)
	for i := 0; i < iterations; i++ {
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}
	wg.Wait()

	if c.Value() != iterations {
		t.Fatalf("Expected %d, got %d", iterations, c.Value())
	}
}

